class BookingHomePage extends StatefulWidget { const BookingHomePage({super.key}); @override State<BookingHomePage> createState()=>_S(); }
class _S extends State<BookingHomePage>{
  List<Doctor> doctors=[]; List<Specialty> specialties=[]; bool loading=true; String? error; String query=''; String selected='';
  @override void initState(){super.initState();load();}
  Future<void> load() async {setState(()=>loading=true);try{final rawD=await ApiService.get('/doctors'); final rawS=await ApiService.get('/specialties'); final ds=(rawD as List).map((e)=>Doctor.fromJson(Map<String,dynamic>.from(e))).where((e)=>e.id.isNotEmpty).toList(); final ss=(rawS as List).map((e)=>Specialty.fromJson(Map<String,dynamic>.from(e))).where((e)=>e.status=='ACTIVE'&&e.name.isNotEmpty).toList(); if(mounted)setState((){doctors=ds;specialties=ss;loading=false;error=null;});}catch(e){if(mounted)setState((){loading=false;error='Không thể tải dữ liệu từ máy chủ.';});}}
  List<Doctor> get filtered=>doctors.where((d){final q=query.toLowerCase(); final okQ=q.isEmpty||d.name.toLowerCase().contains(q)||d.specialty.toLowerCase().contains(q);final okS=selected.isEmpty||d.specialty==selected;return okQ&&okS;}).toList();
  IconData iconFor(String name){final s=name.toLowerCase();if(s.contains('tim'))return Icons.favorite_rounded;if(s.contains('da'))return Icons.face_rounded;if(s.contains('nội'))return Icons.monitor_heart_rounded;if(s.contains('nhi'))return Icons.child_care_rounded;if(s.contains('răng'))return Icons.mood_rounded;if(s.contains('mắt'))return Icons.visibility_rounded;return Icons.medical_services_rounded;}
